INSERT INTO `wp_posts` VALUES (1,1,'2026-11-12 18:15:11','2026-11-12 18:15:11','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2026-11-12 18:15:11','2026-11-12 18:15:11','',0,'http://localhost:8000am/?p=1',0,'post','',1),(2,1,'2026-11-12 18:15:11','2026-11-12 18:15:11','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://localhost:8000am/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-11-12 18:15:11','2026-11-12 18:15:11','',0,'http://localhost:8000am/?page_id=2',0,'page','',0),(3,1,'2026-11-12 18:15:11','2026-11-12 18:15:11','\\n<!-- Highlight Feature Tiles -->\\n<div class=\"legal-highlights-grid\">\\n    <div class=\"legal-highlight-tile\">\\n        <div class=\"tile-icon-wrap icon-purple\"><i class=\"fa-solid fa-lock\"></i></div>\\n        <div class=\"tile-content\">\\n            <h4>SSL 256-Bit Անվտանգություն</h4>\\n            <p>Բոլոր տվյալները գաղտնագրված են բարձրագույն ստանդարտով:</p>\\n        </div>\\n    </div>\\n    <div class=\"legal-highlight-tile\">\\n        <div class=\"tile-icon-wrap icon-green\"><i class=\"fa-solid fa-shield-halved\"></i></div>\\n        <div class=\"tile-content\">\\n            <h4>Քարտերի տվյալներ</h4>\\n            <p>Մենք ԵՐԲԵՔ չենք պահպանում Ձեր բանկային քարտի տվյալները:</p>\\n        </div>\\n    </div>\\n    <div class=\"legal-highlight-tile\">\\n        <div class=\"tile-icon-wrap icon-blue\"><i class=\"fa-solid fa-user\"></i></div>\\n        <div class=\"tile-content\">\\n            <h4>Օգտատիրոջ իրավունք</h4>\\n            <p>Տվյալները թարմացնելու կամ ջնջելու լիակատար վերահսկողություն:</p>\\n        </div>\\n    </div>\\n    <div class=\"legal-highlight-tile\">\\n        <div class=\"tile-icon-wrap icon-pink\"><i class=\"fa-solid fa-scale-balanced\"></i></div>\\n        <div class=\"tile-content\">\\n            <h4>ՀՀ Օրենսդրություն</h4>\\n            <p>Համապատասխանություն Անձնական տվյալների պաշտպանության օրենքին:</p>\\n        </div>\\n    </div>\\n</div>\\n\\n<!-- Section 1 -->\\n<div class=\"legal-section\" id=\"privacy-intro\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">01</span>\\n        <h2>Ընդհանուր դրույթներ և մեր հանձնառությունը</h2>\\n    </div>\\n    <p>ToysLand.am-ը մեծագույն պատասխանատվությամբ է վերաբերվում յուրաքանչյուր հաճախորդի անձնական տվյալների գաղտնիությանը: Սույն Գաղտնիության քաղաքականությունը սահմանում է, թե ինչպես ենք մենք հավաքագրում, օգտագործում, պահպանում և պաշտպանում Ձեր կողմից տրամադրված տեղեկատվությունը՝ համաձայն ՀՀ «Անձնական տվյալների պաշտպանության մասին» օրենքի:</p>\\n</div>\\n\\n<!-- Section 2 -->\\n<div class=\"legal-section\" id=\"data-collected\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">02</span>\\n        <h2>Ի՞նչ անձնական տվյալներ ենք մենք հավաքագրում</h2>\\n    </div>\\n    <p>Պատվերների կատարման և սպասարկման որակի ապահովման նպատակով մենք հավաքագրում ենք միայն անհրաժեշտ նվազագույն տեղեկատվությունը.</p>\\n    \\n    <div class=\"legal-options-grid\">\\n        <div class=\"legal-option-card\">\\n            <div class=\"option-header\">\\n                <span class=\"option-icon\"><i class=\"fa-solid fa-user\"></i></span>\\n                <h3>Նույնականացման տվյալներ</h3>\\n            </div>\\n            <ul class=\"option-features\">\\n                <li>Անուն և ազգանուն:</li>\\n                <li>Կոնտակտային հեռախոսահամար (առաքիչի կապի համար):</li>\\n                <li>Էլեկտրոնային հասցե (պատվերի կարգավիճակի և անդորրագրի համար):</li>\\n            </ul>\\n        </div>\\n\\n        <div class=\"legal-option-card\">\\n            <div class=\"option-header\">\\n                <span class=\"option-icon\"><i class=\"fa-solid fa-location-dot\"></i></span>\\n                <h3>Առաքման տվյալներ</h3>\\n            </div>\\n            <ul class=\"option-features\">\\n                <li>Առաքման քաղաքը և հասցեն (փողոց, շենք, բնակարան):</li>\\n                <li>Փոստային դասիչ (մարզային առաքման դեպքում):</li>\\n                <li>Պատվերի հատուկ նշումներ կամ մեկնաբանություններ:</li>\\n            </ul>\\n        </div>\\n    </div>\\n</div>\\n\\n<!-- Section 3 -->\\n<div class=\"legal-section\" id=\"data-purpose\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">03</span>\\n        <h2>Տվյալների օգտագործման նպատակները</h2>\\n    </div>\\n    <p>Ձեր տվյալներն օգտագործվում են բացառապես հետևյալ նպատակներով.</p>\\n    <ul>\\n        <li>Ձեր գրանցած պատվերների ճշգրիտ ձևակերպում և ժամանակին առաքում:</li>\\n        <li>Պատվերի ընթացքի և կարգավիճակի մասին SMS կամ էլեկտրոնային ծանուցումների ուղարկում:</li>\\n        <li>Հաճախորդների աջակցության ապահովում և հարցերին օպերատիվ պատասխանելը:</li>\\n        <li>Կայքի աշխատանքի բարելավում և անվտանգության ապահովում:</li>\\n    </ul>\\n\\n    <div class=\"legal-alert-box info\">\\n        <span class=\"alert-icon\"><i class=\"fa-solid fa-lock\"></i></span>\\n        <div class=\"alert-text\">\\n            <strong>Երրորդ անձանց չփոխանցման երաշխիք.</strong> Մենք ԵՐԲԵՔ չենք վաճառում կամ տրամադրում Ձեր անձնական տվյալները գովազդային գործակալություններին կամ երրորդ կողմերին: Տվյալները հասանելի են միայն առաքման գործընկերներին՝ բացառապես առաքումը կատարելու նպատակով:\\n        </div>\\n    </div>\\n</div>\\n\\n<!-- Section 4 -->\\n<div class=\"legal-section\" id=\"banking-security\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">04</span>\\n        <h2>Բանկային և վճարային տվյալների անվտանգությունը</h2>\\n    </div>\\n    <div class=\"legal-alert-box success\">\\n        <span class=\"alert-icon\"><i class=\"fa-solid fa-credit-card\"></i></span>\\n        <div class=\"alert-text\">\\n            <strong>ԿԱՐԵՎՈՐ Է ԻՄԱՆԱԼ.</strong> ToysLand-ը ՉԻ ՀԱՎԱՔԱԳՐՈՒՄ, ՉԻ ՄՇԱԿՈՒՄ և ՉԻ ՊԱՀՊԱՆՈՒՄ Ձեր բանկային քարտերի տվյալները (քարտի համար, CVV կոդ, գործողության ժամկետ): Բոլոր առցանց վճարումներն իրականացվում են անմիջապես լիցենզավորված բանկային պրովայդերների և դարպասների (ArCa, IDBank, Ameriabank) պաշտպանված էջերում:\\n        </div>\\n    </div>\\n</div>\\n\\n<!-- Section 5 -->\\n<div class=\"legal-section\" id=\"cookies-policy\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">05</span>\\n        <h2>Cookies (Քուքիներ) քաղաքականություն</h2>\\n    </div>\\n    <p>Կայքի լիարժեք և հարմարավետ աշխատանքի համար մենք օգտագործում ենք Cookies ֆայլեր:</p>\\n    <ul>\\n        <li><strong>Զամբյուղի հիշում՝</strong> Որպեսզի Ձեր ընտրած խաղալիքները չկորչեն էջերը թերթելիս:</li>\\n        <li><strong>Ընտրյալների ցանկ՝</strong> Ձեր նախընտրած ապրանքները պահպանելու համար:</li>\\n        <li><strong>Անվտանգության քուքիներ՝</strong> Կայքի հուսալիությունն ու պաշտպանությունն ապահովելու համար:</li>\\n    </ul>\\n    <p>Դուք կարող եք Ձեր բրաուզերի կարգավորումներից անջատել cookies-ները, սակայն այդ դեպքում զամբյուղի որոշ ֆունկցիաներ կարող են սահմանափակվել:</p>\\n</div>\\n\\n<!-- Section 6 -->\\n<div class=\"legal-section\" id=\"user-rights\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">06</span>\\n        <h2>Ձեր իրավունքները</h2>\\n    </div>\\n    <p>Դուք ունեք լիակատար վերահսկողություն Ձեր տվյալների նկատմամբ.</p>\\n    <ul>\\n        <li>Պահանջել տեղեկատվություն, թե ինչ տվյալներ են պահպանվում Ձեր մասին:</li>\\n        <li>Թարմացնել կամ ուղղել անճշտությունները «Իմ հաշիվը» բաժնից կամ դիմելով մեզ:</li>\\n        <li>Պահանջել Ձեր անձնական տվյալների ամբողջական ջնջումը մեր համակարգից:</li>\\n    </ul>\\n</div>\\n\n','Գաղտնիության քաղաքականություն','','publish','closed','open','','privacy-policy','','','2026-11-12 20:37:23','2026-11-12 20:37:23','',0,'http://localhost:8000am/?page_id=3',0,'page','',0),(4,0,'2026-11-12 18:15:24','2026-11-12 18:15:24','','woocommerce-placeholder','','inherit','open','closed','','woocommerce-placeholder','','','2026-11-12 18:15:24','2026-11-12 18:15:24','',0,'http://localhost:8000am/wp-content/uploads/2026/11/woocommerce-placeholder.webp',0,'attachment','image/webp',0),(5,1,'2026-11-12 18:15:24','2026-11-12 18:15:24','','Shop','','publish','closed','closed','','shop','','','2026-11-12 18:15:24','2026-11-12 18:15:24','',0,'http://localhost:8000am/?page_id=5',0,'page','',0),(6,1,'2026-11-12 18:15:24','2026-11-12 18:15:24','[woocommerce_cart]','Զամբյուղ','','publish','closed','closed','','cart','','','2026-11-12 19:51:13','2026-11-12 19:51:13','',0,'http://localhost:8000am/?page_id=6',0,'page','',0),(7,1,'2026-11-12 18:15:24','2026-11-12 18:15:24','[woocommerce_checkout]','Պատվերի ձևակերպում','','publish','closed','closed','','checkout','','','2026-11-12 20:03:09','2026-11-12 20:03:09','',0,'http://localhost:8000am/?page_id=7',0,'page','',0),(8,1,'2026-11-12 18:15:24','2026-11-12 18:15:24','[woocommerce_my_account]','Իմ հաշիվը','','publish','closed','closed','','my-account','','','2026-11-12 20:17:55','2026-11-12 20:17:55','',0,'http://localhost:8000am/?page_id=8',0,'page','',0),(9,1,'2026-11-12 18:15:24','0000-00-00 00:00:00','<!-- wp:paragraph -->\n<p><b>This is a sample page.</b></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Overview</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Our refund and returns policy lasts 30 days. If 30 days have passed since your purchase, we can’t offer you a full refund or exchange.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>To be eligible for a return, your item must be unused and in the same condition that you received it. It must also be in the original packaging.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Several types of goods are exempt from being returned. Perishable goods such as food, flowers, newspapers or magazines cannot be returned. We also do not accept products that are intimate or sanitary goods, hazardous materials, or flammable liquids or gases.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Additional non-returnable items:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n<li>Gift cards</li>\n<li>Downloadable software products</li>\n<li>Some health and personal care items</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>To complete your return, we require a receipt or proof of purchase.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Please do not send your purchase back to the manufacturer.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>There are certain situations where only partial refunds are granted:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul>\n<li>Book with obvious signs of use</li>\n<li>CD, DVD, VHS tape, software, video game, cassette tape, or vinyl record that has been opened.</li>\n<li>Any item not in its original condition, is damaged or missing parts for reasons not due to our error.</li>\n<li>Any item that is returned more than 30 days after delivery</li>\n</ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Refunds</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Once your return is received and inspected, we will send you an email to notify you that we have received your returned item. We will also notify you of the approval or rejection of your refund.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you are approved, then your refund will be processed, and a credit will automatically be applied to your credit card or original method of payment, within a certain amount of days.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Late or missing refunds</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If you haven’t received a refund yet, first check your bank account again.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Then contact your credit card company, it may take some time before your refund is officially posted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Next contact your bank. There is often some processing time before a refund is posted.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you’ve done all of this and you still have not received your refund yet, please contact us at {email address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Sale items</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Only regular priced items may be refunded. Sale items cannot be refunded.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Exchanges</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>We only replace items if they are defective or damaged. If you need to exchange it for the same item, send us an email at {email address} and send your item to: {physical address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Gifts</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>If the item was marked as a gift when purchased and shipped directly to you, you’ll receive a gift credit for the value of your return. Once the returned item is received, a gift certificate will be mailed to you.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If the item wasn’t marked as a gift when purchased, or the gift giver had the order shipped to themselves to give to you later, we will send a refund to the gift giver and they will find out about your return.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Shipping returns</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>To return your product, you should mail your product to: {physical address}.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You will be responsible for paying for your own shipping costs for returning your item. Shipping costs are non-refundable. If you receive a refund, the cost of return shipping will be deducted from your refund.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Depending on where you live, the time it may take for your exchanged product to reach you may vary.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>If you are returning more expensive items, you may consider using a trackable shipping service or purchasing shipping insurance. We don’t guarantee that we will receive your returned item.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Need help?</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>Contact us at {email} for questions related to refunds and returns.</p>\n<!-- /wp:paragraph -->','Refund and Returns Policy','','draft','closed','closed','','refund_returns','','','2026-11-12 18:15:24','0000-00-00 00:00:00','',0,'http://localhost:8000am/?page_id=9',0,'page','',0),(10,0,'2026-11-12 18:31:40','2026-11-12 18:31:40','<p>Մագնիսական ձկնորսական խաղ՝ ձեռքի շարժումների ճշգրտությունը զարգացնելու համար։</p>','Փայտե ձկնորսական խաղ','<p>Մագնիսական ձկնորսական խաղ՝ ձեռքի շարժումների ճշգրտությունը զարգացնելու համար։</p>','publish','open','closed','','%d6%83%d5%a1%d5%b5%d5%bf%d5%a5-%d5%b1%d5%af%d5%b6%d5%b8%d6%80%d5%bd%d5%a1%d5%af%d5%a1%d5%b6-%d5%ad%d5%a1%d5%b2','','','2026-11-12 18:31:40','2026-11-12 18:31:40','',0,'http://localhost:8000am/?product=%d6%83%d5%a1%d5%b5%d5%bf%d5%a5-%d5%b1%d5%af%d5%b6%d5%b8%d6%80%d5%bd%d5%a1%d5%af%d5%a1%d5%b6-%d5%ad%d5%a1%d5%b2',0,'product','',0),(11,0,'2026-11-12 18:31:40','2026-11-12 18:31:40','<p>Պատկերային քարտեր՝ հիշողության և զույգերը գտնելու հմտությունը զարգացնելու համար։</p>','Հիշողության քարտեր','<p>Պատկերային քարտեր՝ հիշողության և զույգերը գտնելու հմտությունը զարգացնելու համար։</p>','publish','open','closed','','%d5%b0%d5%ab%d5%b7%d5%b8%d5%b2%d5%b8%d6%82%d5%a9%d5%b5%d5%a1%d5%b6-%d6%84%d5%a1%d6%80%d5%bf%d5%a5%d6%80','','','2026-11-12 18:31:40','2026-11-12 18:31:40','',0,'http://localhost:8000am/?product=%d5%b0%d5%ab%d5%b7%d5%b8%d5%b2%d5%b8%d6%82%d5%a9%d5%b5%d5%a1%d5%b6-%d6%84%d5%a1%d6%80%d5%bf%d5%a5%d6%80',0,'product','',0),(12,0,'2026-11-12 18:31:40','2026-11-12 18:31:40','<p>Գունավոր լաբիրինթոս՝ գնդիկը ճիշտ ճանապարհով տեղափոխելու համար։</p>','Մանկական լաբիրինթոս','<p>Գունավոր լաբիրինթոս՝ գնդիկը ճիշտ ճանապարհով տեղափոխելու համար։</p>','publish','open','closed','','%d5%b4%d5%a1%d5%b6%d5%af%d5%a1%d5%af%d5%a1%d5%b6-%d5%ac%d5%a1%d5%a2%d5%ab%d6%80%d5%ab%d5%b6%d5%a9%d5%b8%d5%bd','','','2026-11-12 18:31:40','2026-11-12 18:31:40','',0,'http://localhost:8000am/?product=%d5%b4%d5%a1%d5%b6%d5%af%d5%a1%d5%af%d5%a1%d5%b6-%d5%ac%d5%a1%d5%a2%d5%ab%d6%80%d5%ab%d5%b6%d5%a9%d5%b8%d5%bd',0,'product','',0),(13,0,'2026-11-12 18:31:40','2026-11-12 18:31:40','<p>Շերտավոր խաղ՝ հավասարակշռությունն ու կենտրոնացումը զարգացն