\"} -->\n<div style=\"height:40px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:pattern {\"slug\":\"woocommerce/cart-new-in-store-message\"} /-->\n\n<!-- wp:woocommerce/product-new {\"columns\":4,\"rows\":1} /--></div>\n<!-- /wp:woocommerce/empty-cart-block --></div>\n<!-- /wp:woocommerce/cart -->','Cart','','inherit','closed','closed','','6-revision-v1','','','2026-11-12 18:55:36','2026-11-12 18:55:36','',6,'http://127.0.0.1:8000/?p=66',0,'revision','',0),(67,0,'2026-11-12 19:46:49','2026-11-12 19:46:49','','','','draft','closed','closed','','','','','2026-11-12 19:46:49','2026-11-12 19:46:49','',0,'http://127.0.0.1:8000/?post_type=shop_order_placehold&p=67',0,'shop_order_placehold','',3),(68,0,'2026-11-12 19:51:13','2026-11-12 19:51:13','[woocommerce_cart]','Զամբյուղ','','inherit','closed','closed','','6-revision-v1','','','2026-11-12 19:51:13','2026-11-12 19:51:13','',6,'http://127.0.0.1:8000/?p=68',0,'revision','',0),(69,0,'2026-11-12 20:03:09','2026-11-12 20:03:09','[woocommerce_checkout]','Պատվերի ձևակերպում','','inherit','closed','closed','','7-revision-v1','','','2026-11-12 20:03:09','2026-11-12 20:03:09','',7,'http://127.0.0.1:8000/?p=69',0,'revision','',0),(70,0,'2026-11-12 20:10:19','2026-11-12 20:10:19','','','','draft','closed','closed','','','','','2026-11-12 20:10:19','2026-11-12 20:10:19','',0,'http://127.0.0.1:8000/?post_type=shop_order_placehold&p=70',0,'shop_order_placehold','',3),(71,0,'2026-11-12 20:17:55','2026-11-12 20:17:55','[woocommerce_my_account]','Իմ հաշիվը','','inherit','closed','closed','','8-revision-v1','','','2026-11-12 20:17:55','2026-11-12 20:17:55','',8,'http://127.0.0.1:8000/?p=71',0,'revision','',0),(72,0,'2026-11-12 20:23:15','2026-11-12 20:23:15','','','','draft','closed','closed','','','','','2026-11-12 20:23:15','2026-11-12 20:23:15','',0,'http://127.0.0.1:8000/?post_type=shop_order_placehold&p=72',0,'shop_order_placehold','',3),(73,0,'2026-11-12 20:35:22','2026-11-12 20:35:22','\\n<!-- Highlight Feature Tiles -->\\n<div class=\"legal-highlights-grid\">\\n    <div class=\"legal-highlight-tile\">\\n        <div class=\"tile-icon-wrap icon-purple\"><i class=\"fa-solid fa-file-contract\"></i></div>\\n        <div class=\"tile-content\">\\n            <h4>Հրապարակային Օֆերտա</h4>\\n            <p>Պաշտոնական պայմանագիր կայքից օգտվող յուրաքանչյուրի հետ:</p>\\n        </div>\\n    </div>\\n    <div class=\"legal-highlight-tile\">\\n        <div class=\"tile-icon-wrap icon-green\"><i class=\"fa-solid fa-shapes\"></i></div>\\n        <div class=\"tile-content\">\\n            <h4>Օրիգինալ ապրանքներ</h4>\\n            <p>100% ստուգված և անվտանգ մանկական խաղալիքներ:</p>\\n        </div>\\n    </div>\\n    <div class=\"legal-highlight-tile\">\\n        <div class=\"tile-icon-wrap icon-blue\"><i class=\"fa-solid fa-tag\"></i></div>\\n        <div class=\"tile-content\">\\n            <h4>Թափանցիկ գներ</h4>\\n            <p>Բոլոր գները նշված են ՀՀ դրամով՝ ներառյալ հարկերը:</p>\\n        </div>\\n    </div>\\n    <div class=\"legal-highlight-tile\">\\n        <div class=\"tile-icon-wrap icon-pink\"><i class=\"fa-solid fa-scale-balanced\"></i></div>\\n        <div class=\"tile-content\">\\n            <h4>Սպառողի իրավունք</h4>\\n            <p>Լիակատար պաշտպանություն ՀՀ օրենսդրության համաձայն:</p>\\n        </div>\\n    </div>\\n</div>\\n\\n<!-- Section 1 -->\\n<div class=\"legal-section\" id=\"terms-general\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">01</span>\\n        <h2>Ընդհանուր դրույթներ</h2>\\n    </div>\\n    <p>Սույն Օգտագործման պայմանները (այսուհետ՝ «Պայմաններ») հանդիսանում են հրապարակային օֆերտա «ToysLand» առցանց խանութի (կայք՝ ToysLand.am) և կայքից օգտվող ֆիզիկական անձանց (այսուհետ՝ «Գնորդ» կամ «Օգտատեր») միջև:</p>\\n    <p>Կայքում գրանցվելով, պատվեր կատարելով կամ կայքից օգտվելով՝ Օգտատերը հաստատում է, որ ամբողջությամբ ընթերցել, հասկացել և անվերապահորեն ընդունում է սույն Պայմանները:</p>\\n</div>\\n\\n<!-- Section 2 -->\\n<div class=\"legal-section\" id=\"terms-orders\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">02</span>\\n        <h2>Պատվերների գրանցումը և գործարքի կնքումը</h2>\\n    </div>\\n    <ul>\\n        <li>Գնորդը պատվերը կարող է գրանցել կայքի զամբյուղի միջոցով ինքնուրույն կամ հեռախոսազանգով՝ օպերատորի աջակցությամբ:</li>\\n        <li>Պատվերը համարվում է հաստատված, երբ համակարգը գեներացնում է պատվերի անհատական համարը և ուղարկում հաստատման ծանուցում:</li>\\n        <li>Գնորդը պատասխանատվություն է կրում իր տրամադրած տվյալների (հեռախոսահամար, առաքման հասցե, անուն) ճշգրտության համար:</li>\\n    </ul>\\n</div>\\n\\n<!-- Section 3 -->\\n<div class=\"legal-section\" id=\"terms-pricing\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">03</span>\\n        <h2>Գները, ապրանքների նկարագրությունները և զեղչերը</h2>\\n    </div>\\n    <p>Կայքում ներկայացված բոլոր ապրանքների գները նշված են ՀՀ դրամով (֏) և ներառում են ՀՀ օրենսդրությամբ նախատեսված բոլոր հարկերը:</p>\\n    <div class=\"legal-alert-box info\">\\n        <span class=\"alert-icon\"><i class=\"fa-solid fa-lightbulb\"></i></span>\\n        <div class=\"alert-text\">\\n            <strong>Ակցիաներ և զեղչեր.</strong> Խանութն իրավունք ունի կազմակերպելու պարբերական ակցիաներ, զեղչեր և հատուկ առաջարկներ: Ակցիաների պայմանները հրապարակվում են կայքում և գործում են նշված ժամանակահատվածում կամ մինչև ապրանքների առկայության ավարտը:\\n        </div>\\n    </div>\\n</div>\\n\\n<!-- Section 4 -->\\n<div class=\"legal-section\" id=\"terms-shipping-transfer\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">04</span>\\n        <h2>Առաքում և սեփականության իրավունքի փոխանցում</h2>\\n    </div>\\n    <ul>\\n        <li>Առաքումն իրականացվում է «Առաքում և վճարում» էջում նշված պայմաններին և սակագներին համապատասխան:</li>\\n        <li>Ապրանքի սեփականության իրավունքը, ինչպես նաև դրա պատահական վնասման կամ կորստի ռիսկը Գնորդին է անցնում ապրանքն առաքիչից ստանալու և վճարումը կատարելու պահից:</li>\\n    </ul>\\n</div>\\n\\n<!-- Section 5 -->\\n<div class=\"legal-section\" id=\"terms-ip\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">05</span>\\n        <h2>Մտավոր սեփականության իրավունքներ</h2>\\n    </div>\\n    <p>Կայքում տեղադրված բոլոր նյութերը՝ ներառյալ ToysLand ապրանքային նշանը, լոգոն, տեքստերը, դիզայնը, ծրագրային կոդը և լուսանկարները, պաշտպանված են մտավոր սեփականության իրավունքով: Դրանց ապօրինի օգտագործումը, պատճենումը կամ վերարտադրումն առանց գրավոր թույլտվության արգելվում է:</p>\\n</div>\\n\\n<!-- Section 6 -->\\n<div class=\"legal-section\" id=\"terms-disputes\">\\n    <div class=\"section-header-wrap\">\\n        <span class=\"section-number\">06</span>\\n        <h2>Պատասխանատվություն և վեճերի լուծում</h2>\\n    </div>\\n    <p>Կողմերի միջև ծագած բոլոր վեճերը և տարաձայնությունները լուծվում են բանակցությունների և փոխադարձ համաձայնության միջոցով: Համաձայնություն ձեռք չբերելու դեպքում վեճերը ենթակա են լուծման Հայաստանի Հանրապետության դատարաններում՝ ՀՀ օրենսդրությամբ սահմանված կարգով:</p>\\n</div>\\n\n','Օգտագործման պայմաններ','','publish','closed','closed','','terms','','','2026-11-12 20:37:23','2026-11-12 20:37:23','',0,'http://127.0.0.1:8000/terms/',0,'page','',0),(74,0,'2026-11-12 20:35:22','2026-11-12 20:35:22','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost:8000am.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Գաղտնիության քաղաքականություն','','inherit','closed','closed','','3-revision-v1','','','2026-11-12 20:35:22','2026-11-12 20:35:22','',3,'http://127.0.0.1:8000/?p=74',0,'revision','',0),(75,0,'2026-11-12 20:35:22','2026-11-12 20:35:22','Առաքումն իրականացվում է Երևանում 1 աշխատանքային օրվա ընթացքում (արժեքը՝ 1000 ֏, 15 000 ֏-ից բարձր գնումների դեպքում՝ ԱՆՎՃԱՐ): Մարզեր առաքումն իրականացվում է 2-3 աշխատանքային օրում:','Առաքում և վճարում','','inherit','closed','closed','','64-revision-v1','','','2026-11-12 20:35:22','2026-11-12 20:35:22','',64,'http://127.0.0.1:8000/?p=75',0,'revision','',0),(76,0,'2026-11-12 20:35:22','2026-11-12 20:35:22','Խաղալիքները կարող են վերադարձվել կամ փոխանակվել 14 օրվա ընթացքում՝ գործարանային փաթեթավորման պահպանման դեպքում:','Վերադարձ և երաշխիք','','inherit','closed','closed','','65-revision-v1','','','2026-11-12 20:35:22','2026-11-12 20:35:22','',65,'http://127.0.0.1:8000/?p=76',0,'revision','',0),(77,0,'2026-11-12 20:37:23','2026-11-12 20:37:23','\\n<!-- Highlig